// Brixelizer GI's shader blob accessor (ADR 0090), in place of the SDK's
// sdk/src/backends/shared/blob_accessors/ffx_brixelizergi_shaderblobs.cpp, which includes
// headers generated by the SDK's shader compiler: the reflection and the permutation table
// in permutations_brixelizergi.inc, the SPIR-V from Rust (src/blobs.rs), both from
// examples/ffx_shaders.rs. Only the permutations the engine creates contexts for are there
// (inverted depth, the denoiser on, specular on or off).

#include "ffx_engine.h"

#include <FidelityFX/host/ffx_util.h>
#include "ffx_brixelizergi_shaderblobs.h"
#include <FidelityFX/gpu/brixelizergi/ffx_brixelizergi_resources.h>
#include "brixelizergi/ffx_brixelizergi_private.h"

#include <cstring>

namespace {

#include "permutations_brixelizergi.inc"

}  // namespace

FfxErrorCode brixelizerGIGetPermutationBlobByIndex(FfxBrixelizerGIPass passId, uint32_t permutationOptions, FfxShaderBlob* outBlob)
{
    // The generator's shaders follow `FfxBrixelizerGIPass`, every one with a 16-bit variant.
    if (uint32_t(passId) >= uint32_t(FFX_BRIXELIZER_GI_PASS_COUNT))
    {
        std::memset(outBlob, 0, sizeof(FfxShaderBlob));
        return FFX_ERROR_INVALID_ARGUMENT;
    }
    const uint32_t fp16 = FFX_CONTAINS_FLAG(permutationOptions, BRIXELIZER_GI_SHADER_PERMUTATION_ALLOW_FP16) ? 1 : 0;
    // The option bits below FORCE_WAVE64: the defines of the permutation.
    const uint32_t options = permutationOptions & (BRIXELIZER_GI_SHADER_PERMUTATION_FORCE_WAVE64 - 1);
    return engineFfxBlob(ENGINE_FFX_BRIXELIZER_GI, g_permutations, sizeof(g_permutations) / sizeof(g_permutations[0]),
                         g_reflection, MODULE_COUNT, uint32_t(passId), fp16, options, outBlob);
}

FfxErrorCode brixelizerGIIsWave64(uint32_t permutationOptions, bool& isWave64)
{
    // The same module either way on Vulkan: the backend requests the subgroup size.
    isWave64 = FFX_CONTAINS_FLAG(permutationOptions, BRIXELIZER_GI_SHADER_PERMUTATION_FORCE_WAVE64);
    return FFX_OK;
}
